/* Challenge modes: harder kinds of questions, each with a lesson in `fact`.
 * lvl 4 = Parable Pros (what Jesus' teachings mean), 5 = Prophecy Hunters (promise → fulfillment),
 * 6 = Scholars (languages, places, history, how the Bible came together), 7 = Holy of Holies (unlocked by beating 1–6).
 * Same shape as js/data.js: the first entry in `a` is the correct answer. */
window.THP = window.THP || {};

THP.QUESTIONS.push(
  // ---------- Parable Pros: what it MEANS ----------
  { lvl: 4, cat: "The Sower", q: "In the parable of the sower, what happens to the seed that falls on the path?", a: ["Birds eat it up", "It grows a huge crop", "Thorns choke it", "It dries up in the sun"], ref: "Matthew 13:4, 19", fact: "Jesus explained the birds are like the evil one snatching God's message away before it can take root." },
  { lvl: 4, cat: "The Sower", q: "What do the seeds on rocky ground stand for?", a: ["People who start strong but quit when trouble comes", "People who never hear about God", "People who worry about money", "People who grow a huge harvest"], ref: "Matthew 13:20–21", fact: "Faith needs roots. Without roots, it dries up when life gets hard." },
  { lvl: 4, cat: "The Sower", q: "In the sower parable, what are the thorns that choke the plants?", a: ["Worries and the love of money", "Mean people", "Too much rain", "Hard questions"], ref: "Matthew 13:22", fact: "Worry and wanting stuff can crowd God out of our lives, like weeds in a garden." },
  { lvl: 4, cat: "The Sower", q: "What does the seed on good soil produce?", a: ["A crop 30, 60 or 100 times what was planted", "Exactly one plant", "Nothing until winter", "A single giant tree"], ref: "Matthew 13:23", fact: "When someone hears God's word and understands it, their life produces far more good than you'd expect." },
  { lvl: 4, cat: "Kingdom Stories", q: "What is Jesus' point when He compares God's kingdom to a mustard seed?", a: ["It starts tiny but grows huge", "It is hard to find", "It tastes spicy", "It only grows in deserts"], ref: "Matthew 13:31–32", fact: "God's kingdom started with a few followers and grew to fill the whole world." },
  { lvl: 4, cat: "Kingdom Stories", q: "Jesus said the kingdom is like yeast mixed into flour. What does yeast do?", a: ["Spreads through the whole batch of dough", "Makes the bread taste sweet", "Keeps bugs away", "Turns flour into water"], ref: "Matthew 13:33", fact: "A little bit of God's kingdom quietly changes everything around it." },
  { lvl: 4, cat: "Kingdom Stories", q: "A man found treasure hidden in a field. What did he do?", a: ["Sold everything he had to buy the field", "Told everyone in town", "Left it there", "Gave it to the king"], ref: "Matthew 13:44", fact: "Knowing God is worth more than everything else we own, and the man was happy to trade it all." },
  { lvl: 4, cat: "Kingdom Stories", q: "What did the merchant do when he found one pearl of great value?", a: ["Sold everything to buy it", "Hid it in the sand", "Traded it for two smaller pearls", "Threw it back into the sea"], ref: "Matthew 13:45–46", fact: "Like the treasure story, this teaches that God's kingdom is the most valuable thing there is." },
  { lvl: 4, cat: "Kingdom Stories", q: "In the parable of the weeds, what did the owner say to do with the weeds in his wheat field?", a: ["Let both grow until harvest, then separate them", "Burn the whole field right away", "Pull every weed today", "Sell the field"], ref: "Matthew 13:30", fact: "God is patient. He will sort out good and evil at the end, at the right time." },
  { lvl: 4, cat: "Lost & Found", q: "What does Jesus say happens in heaven when one sinner turns back to God?", a: ["There is rejoicing", "Nobody notices", "The angels sleep", "A trumpet warns everyone"], ref: "Luke 15:7, 10", fact: "Every single person matters to God. Heaven throws a party when even one comes home." },
  { lvl: 4, cat: "Lost & Found", q: "In the parable of the lost coin, how many silver coins did the woman have before she lost one?", a: ["10", "100", "3", "40"], ref: "Luke 15:8–9", fact: "She still had nine, but she swept the whole house for the one. That's how God searches for us." },
  { lvl: 4, cat: "Lost & Found", q: "What did the younger son ask his father for at the start of the prodigal son story?", a: ["His share of the inheritance early", "A new robe", "A job on the farm", "Permission to get married"], ref: "Luke 15:12", fact: "Asking for the inheritance early was like saying, \"I want your stuff more than I want you.\"" },
  { lvl: 4, cat: "Lost & Found", q: "When the lost son came home, what did his father do first?", a: ["Ran to him, hugged and kissed him", "Made him a servant", "Waited for an apology", "Sent him away"], ref: "Luke 15:20", fact: "In that culture, respected fathers didn't run in public. This one did. That's how eager God is to forgive." },
  { lvl: 4, cat: "Lost & Found", q: "How did the older brother react to the party for his returning brother?", a: ["He was angry and wouldn't go in", "He planned the whole party", "He ran away too", "He gave a speech"], ref: "Luke 15:28–30", fact: "The story warns \"good\" people not to resent God's grace for others." },
  { lvl: 4, cat: "Love Your Neighbor", q: "Jesus told the parable of the Good Samaritan to answer which question?", a: ["\"Who is my neighbor?\"", "\"How do I get rich?\"", "\"Where should we eat?\"", "\"When will the world end?\""], ref: "Luke 10:29", fact: "Jesus flipped the question: don't ask who counts as your neighbor. Be a neighbor to anyone in need." },
  { lvl: 4, cat: "Love Your Neighbor", q: "Which two people walked past the hurt man in the Good Samaritan story?", a: ["A priest and a Levite", "Two soldiers", "A king and a prince", "Two fishermen"], ref: "Luke 10:31–32", fact: "A priest and a Levite walked past. The Samaritan, the one the listeners least expected, stopped to help." },
  { lvl: 4, cat: "Love Your Neighbor", q: "Why was it surprising that the hero of the story was a Samaritan?", a: ["Jews and Samaritans usually didn't get along", "Samaritans couldn't travel", "Samaritans were all doctors", "Samaritans lived far away in Egypt"], ref: "Luke 10:33; John 4:9", fact: "Jesus made the hero someone His listeners disliked. Love crosses every line people draw." },
  { lvl: 4, cat: "Love Your Neighbor", q: "In Matthew 25, Jesus said that when we help people who are hungry, sick or in prison, we are really helping...", a: ["Jesus Himself", "The government", "Only ourselves", "The angels"], ref: "Matthew 25:40", fact: "\"Whatever you did for one of the least of these brothers and sisters of mine, you did for me.\"" },
  { lvl: 4, cat: "Wise Choices", q: "In the story of the two builders, who is like the wise man who built on rock?", a: ["Someone who hears Jesus' words and does them", "Someone who builds fast", "Someone with lots of money", "Someone who never goes outside"], ref: "Matthew 7:24–27", fact: "Hearing isn't enough. Doing what Jesus says is what keeps us standing when storms come." },
  { lvl: 4, cat: "Wise Choices", q: "In the parable of the ten bridesmaids, what did the five foolish ones forget?", a: ["Extra oil for their lamps", "Their invitations", "Their shoes", "A gift for the bride"], ref: "Matthew 25:3, 13", fact: "Just like in this game: keep your lamp ready! Jesus said, \"Keep watch, because you do not know the day or the hour.\"" },
  { lvl: 4, cat: "Wise Choices", q: "In the parable of the talents, what did the servant with one bag of gold do?", a: ["Buried it in the ground", "Doubled it", "Gave it to the poor", "Spent it on a party"], ref: "Matthew 25:18, 25", fact: "God gives everyone gifts. He wants us to use them, not hide them because we're afraid." },
  { lvl: 4, cat: "Wise Choices", q: "What did the master say to the servants who used his money well?", a: ["\"Well done, good and faithful servant!\"", "\"You can keep it all.\"", "\"Next time, ask first.\"", "\"Why did you take so long?\""], ref: "Matthew 25:21", fact: "Faithful in small things leads to being trusted with bigger things." },
  { lvl: 4, cat: "Wise Choices", q: "What did the rich fool plan to do with his huge harvest?", a: ["Build bigger barns and take life easy", "Share it with his neighbors", "Give it to the temple", "Sell it to buy a ship"], ref: "Luke 12:18–21", fact: "God called him a fool because he was rich in stuff but not rich toward God." },
  { lvl: 4, cat: "Forgiveness", q: "When Peter asked if he should forgive someone seven times, what did Jesus say?", a: ["Way more than seven: keep on forgiving", "Seven is perfect", "Only forgive once", "Only forgive family"], ref: "Matthew 18:21–22", fact: "Jesus' number was so big the point is clear: stop counting and keep forgiving." },
  { lvl: 4, cat: "Forgiveness", q: "In the parable of the unforgiving servant, what did the servant do right after the king canceled his huge debt?", a: ["Demanded a small debt from another servant", "Threw a party for the king", "Forgave everyone he knew", "Moved to another country"], ref: "Matthew 18:27–30", fact: "God has forgiven us so much. That's why we should forgive others too." },
  { lvl: 4, cat: "Prayer", q: "In the story of the Pharisee and the tax collector, who went home right with God?", a: ["The tax collector who asked for mercy", "The Pharisee who bragged", "Both of them", "Neither of them"], ref: "Luke 18:13–14", fact: "God listens to humble hearts, not show-offs." },
  { lvl: 4, cat: "Prayer", q: "Jesus told the parable of the persistent widow to teach that we should...", a: ["Always pray and never give up", "Only pray once", "Pray loudly in public", "Stop asking God for things"], ref: "Luke 18:1", fact: "If even an unfair judge gives in to someone who keeps asking, how much more will our loving God listen?" },
  { lvl: 4, cat: "Prayer", q: "In the Lord's Prayer, what does \"Give us today our daily bread\" teach us?", a: ["To trust God for what we need each day", "To bake every morning", "To only eat bread", "To save food for years"], ref: "Matthew 6:11", fact: "Like manna in the desert, God gives what we need one day at a time." },
  { lvl: 4, cat: "Prayer", q: "Jesus said when you pray, you should...", a: ["Go to a private place, not show off", "Stand on a street corner", "Use as many words as possible", "Only pray in the temple"], ref: "Matthew 6:5–6", fact: "Prayer is talking with your Father, not performing for an audience." },
  { lvl: 4, cat: "Prayer", q: "\"Ask and it will be given; seek and you will find; ___ and the door will be opened.\"", a: ["knock", "wait", "shout", "run"], ref: "Matthew 7:7", fact: "Jesus invites us to keep coming to God with what we need." },
  { lvl: 4, cat: "God's Generosity", q: "In the parable of the vineyard workers, how much did the workers hired last get paid?", a: ["The same as everyone else", "Nothing", "Half as much", "Double"], ref: "Matthew 20:9–15", fact: "God's grace isn't a paycheck we earn. He is generous to everyone who comes." },
  { lvl: 4, cat: "God's Generosity", q: "In the parable of the great banquet, who did the host invite after the guests made excuses?", a: ["The poor and people with disabilities", "Only the king's friends", "Nobody, he canceled it", "Only his family"], ref: "Luke 14:21", fact: "God's party is open to everyone, especially people the world overlooks." },
  { lvl: 4, cat: "God's Generosity", q: "In Jesus' story of two sons, which son actually did what his father asked?", a: ["The one who said no but then went", "The one who said yes but didn't go", "Both sons", "Neither son"], ref: "Matthew 21:28–31", fact: "What we do matters more than what we say." },
  { lvl: 4, cat: "Sermon on the Mount", q: "Jesus called His followers \"the salt of the earth\" and \"the ___ of the world.\"", a: ["light", "king", "rock", "bread"], ref: "Matthew 5:13–14", fact: "Salt adds flavor and light shows the way. Christians are meant to make the world better." },
  { lvl: 4, cat: "Sermon on the Mount", q: "Jesus said people don't light a lamp and put it...", a: ["Under a bowl", "On a stand", "In a window", "On a hill"], ref: "Matthew 5:15–16", fact: "\"Let your light shine before others, that they may see your good deeds and glorify your Father.\"" },
  { lvl: 4, cat: "Sermon on the Mount", q: "\"Blessed are the peacemakers, for they will be called...\"", a: ["children of God", "kings of the earth", "the strongest", "the richest"], ref: "Matthew 5:9", fact: "When you make peace instead of fights, you're acting like God's own family." },
  { lvl: 4, cat: "Sermon on the Mount", q: "\"Blessed are the meek, for they will inherit...\"", a: ["the earth", "a castle", "gold", "nothing"], ref: "Matthew 5:5", fact: "Meek doesn't mean weak. It means gentle strength that trusts God instead of pushing others around." },
  { lvl: 4, cat: "Sermon on the Mount", q: "\"Blessed are the pure in heart, for they will...\"", a: ["see God", "never be sad", "win every game", "be famous"], ref: "Matthew 5:8", fact: "A heart that wants God more than anything gets to know Him up close." },
  { lvl: 4, cat: "Sermon on the Mount", q: "What did Jesus say to do for people who treat you badly?", a: ["Love them and pray for them", "Get even", "Ignore them forever", "Tell everyone about it"], ref: "Matthew 5:44", fact: "This is one of the hardest and most powerful things Jesus taught." },
  { lvl: 4, cat: "Sermon on the Mount", q: "If someone slaps you on the right cheek, Jesus said to...", a: ["Turn the other cheek too", "Slap them back", "Run away", "Call the guards"], ref: "Matthew 5:39", fact: "Jesus taught His followers to break the cycle of revenge." },
  { lvl: 4, cat: "Sermon on the Mount", q: "Complete the Golden Rule: \"Do to others what...\"", a: ["you would have them do to you", "they did to you first", "your parents tell you", "makes you happy"], ref: "Matthew 7:12", fact: "Jesus said this one sentence sums up the Law and the Prophets." },
  { lvl: 4, cat: "Sermon on the Mount", q: "\"Where your treasure is, there your ___ will be also.\"", a: ["heart", "house", "money", "family"], ref: "Matthew 6:21", fact: "Whatever we care about most is what our hearts chase." },
  { lvl: 4, cat: "Sermon on the Mount", q: "To teach us not to worry, Jesus pointed to...", a: ["Birds and wildflowers that God takes care of", "Kings and their armies", "Mountains and rivers", "The stars at night"], ref: "Matthew 6:26–30", fact: "If God feeds the birds and dresses the flowers, He will take care of you." },
  { lvl: 4, cat: "Sermon on the Mount", q: "What did Jesus say to seek first?", a: ["God's kingdom and His righteousness", "A good job", "Lots of friends", "Safety"], ref: "Matthew 6:33", fact: "Put God first, and trust Him to give you what you really need." },
  { lvl: 4, cat: "Sermon on the Mount", q: "Why did Jesus tell people to enter through the narrow gate?", a: ["It leads to life", "It's a shortcut", "It's less crowded at lunch", "The wide gate is locked"], ref: "Matthew 7:13–14", fact: "The easy road everyone takes isn't always the right one. Following Jesus leads to real life." },
  { lvl: 4, cat: "Sermon on the Mount", q: "Before pointing out the speck in your friend's eye, Jesus said to first remove...", a: ["The plank in your own eye", "Your shoes", "The speck with tweezers", "Your hat"], ref: "Matthew 7:3–5", fact: "Deal with your own faults before you judge someone else's." },
  { lvl: 4, cat: "Sermon on the Mount", q: "Jesus said you cannot serve both God and...", a: ["money", "your parents", "your country", "your friends"], ref: "Matthew 6:24", fact: "Only one thing can be number one in your heart." },
  { lvl: 4, cat: "Sermon on the Mount", q: "When you give to people in need, Jesus said...", a: ["Don't let your left hand know what your right hand is doing", "Announce it with trumpets", "Give only to friends", "Write your name on the gift"], ref: "Matthew 6:3–4", fact: "Give quietly. God sees what's done in secret." },
  { lvl: 4, cat: "I Am Sayings", q: "Jesus said, \"I am the bread of life.\" What did He promise?", a: ["Whoever comes to Him will never go hungry", "Free bread every day", "Bakeries in every town", "No more vegetables"], ref: "John 6:35", fact: "Jesus meant a deeper hunger. Only He can fill the empty place in our hearts." },
  { lvl: 4, cat: "I Am Sayings", q: "\"I am the light of the world. Whoever follows me will never...\"", a: ["walk in darkness", "be tired", "get lost at sea", "need sleep"], ref: "John 8:12", fact: "Following Jesus is like walking with a light that shows the way." },
  { lvl: 4, cat: "I Am Sayings", q: "Jesus said He is the vine and we are the branches. What happens apart from Him?", a: ["We can do nothing", "We grow faster", "We become trees", "Nothing changes"], ref: "John 15:5", fact: "A branch cut off from the vine can't grow fruit. We need to stay connected to Jesus." },
  { lvl: 4, cat: "I Am Sayings", q: "\"I am the way and the truth and the ___.\"", a: ["life", "light", "door", "king"], ref: "John 14:6", fact: "Jesus said, \"No one comes to the Father except through me.\"" },
  { lvl: 4, cat: "I Am Sayings", q: "To whom did Jesus say, \"I am the resurrection and the life\"?", a: ["Martha", "Peter", "Pilate", "Nicodemus"], ref: "John 11:25", fact: "He said it to Martha, right before He raised her brother Lazarus from the dead." },
  { lvl: 4, cat: "I Am Sayings", q: "Jesus called Himself \"the good shepherd.\" What did He say a good shepherd does?", a: ["Lays down his life for the sheep", "Sells the slowest sheep", "Sleeps all day", "Builds a big wall"], ref: "John 10:11", fact: "Jesus did exactly that on the cross." },
  { lvl: 4, cat: "Upside-Down Kingdom", q: "Who did Jesus say is the greatest in the kingdom of heaven?", a: ["Whoever is humble like a little child", "The strongest soldier", "The richest person", "The best speaker"], ref: "Matthew 18:3–4", fact: "In God's kingdom, being humble matters more than being important." },
  { lvl: 4, cat: "Upside-Down Kingdom", q: "Why did Jesus say Mary had chosen what is better than Martha?", a: ["She sat and listened to Him", "She cooked a better meal", "She cleaned the house", "She invited more guests"], ref: "Luke 10:39–42", fact: "Being busy for Jesus is good. Spending time with Jesus is better." },
  { lvl: 4, cat: "Upside-Down Kingdom", q: "Why did Jesus say the poor widow gave more than the rich people?", a: ["She gave all she had", "Her coins were gold", "She gave first", "She gave the loudest"], ref: "Mark 12:43–44", fact: "God looks at the heart behind a gift, not the size of it." },
  { lvl: 4, cat: "Upside-Down Kingdom", q: "What did Jesus tell the rich young man to do?", a: ["Sell his things, give to the poor, and follow Him", "Build a temple", "Become a priest", "Keep his money safe"], ref: "Mark 10:21–22", fact: "The man went away sad because he loved his stuff too much." },
  { lvl: 4, cat: "Upside-Down Kingdom", q: "Jesus said it's easier for a camel to go through the eye of a needle than for...", a: ["a rich person to enter God's kingdom", "a fish to climb a tree", "a king to say sorry", "a turtle to fly"], ref: "Mark 10:25–27", fact: "Then He said, \"All things are possible with God.\"" },
  { lvl: 4, cat: "Upside-Down Kingdom", q: "When Jesus washed His disciples' feet, what was He teaching?", a: ["To serve each other humbly", "That feet should always be clean", "That dinner was ready", "That Peter was in trouble"], ref: "John 13:14–15", fact: "The King of everything did a servant's job to show us how to love." },
  { lvl: 4, cat: "Upside-Down Kingdom", q: "Jesus said everyone will know we are His disciples if we...", a: ["love one another", "go to the temple", "wear special clothes", "memorize the most verses"], ref: "John 13:34–35", fact: "Love is the badge that shows the world who we follow." },
  { lvl: 4, cat: "New Life", q: "Jesus told Nicodemus that no one can see the kingdom of God unless they are...", a: ["born again", "very old", "from Jerusalem", "a priest"], ref: "John 3:3", fact: "Being \"born again\" means getting a brand-new start with God through His Spirit." },
  { lvl: 4, cat: "New Life", q: "What did Jesus offer the Samaritan woman at the well?", a: ["Living water", "A bucket", "Bread and fish", "Money for the trip"], ref: "John 4:10, 14", fact: "He meant eternal life that satisfies forever, like a spring inside you." },
  { lvl: 4, cat: "New Life", q: "What did Jesus tell His followers to do in the Great Commission?", a: ["Go and make disciples of all nations", "Build the biggest church", "Stay in Jerusalem forever", "Wait quietly"], ref: "Matthew 28:19–20", fact: "He added, \"I am with you always, to the very end of the age.\"" },

  // ---------- Prophecy Hunters: promise → fulfillment ----------
  { lvl: 5, cat: "Birth of the King", q: "Which prophet said the Messiah would come from Bethlehem?", a: ["Micah", "Jonah", "Amos", "Ezekiel"], ref: "Micah 5:2; Matthew 2:5–6", fact: "About 700 years before Jesus, Micah named the tiny town. The religious leaders quoted it to King Herod." },
  { lvl: 5, cat: "Birth of the King", q: "Isaiah said a virgin would have a son called Immanuel. What does Immanuel mean?", a: ["God with us", "Prince of peace", "King of kings", "The Lord saves"], ref: "Isaiah 7:14; Matthew 1:23", fact: "In Jesus, God didn't just send a message. He came to be with us in person." },
  { lvl: 5, cat: "Birth of the King", q: "Which Gospel connects Isaiah's \"Immanuel\" prophecy to Jesus' birth?", a: ["Matthew", "Mark", "John", "Acts"], ref: "Matthew 1:22–23", fact: "Matthew often points out how Jesus fulfilled the Old Testament Scriptures." },
  { lvl: 5, cat: "Birth of the King", q: "Isaiah 9:6 calls the coming child \"Wonderful Counselor, Mighty God, Everlasting Father, and...\"", a: ["Prince of Peace", "Lion of Judah", "Son of David", "Lamb of God"], ref: "Isaiah 9:6", fact: "You often hear this verse at Christmas because it describes who Jesus is." },
  { lvl: 5, cat: "Birth of the King", q: "Isaiah said a shoot would come from the stump of ___, King David's father.", a: ["Jesse", "Boaz", "Saul", "Abraham"], ref: "Isaiah 11:1", fact: "David's royal family looked like a dead stump, but God promised new life would grow from it: Jesus." },
  { lvl: 5, cat: "Birth of the King", q: "\"Out of Egypt I called my son\" came true when...", a: ["Jesus' family came back from Egypt", "Moses parted the Red Sea", "Joseph became a ruler", "Paul sailed to Rome"], ref: "Hosea 11:1; Matthew 2:15", fact: "Hosea was talking about Israel leaving Egypt. Matthew shows Jesus living out Israel's story perfectly." },
  { lvl: 5, cat: "Birth of the King", q: "When baby Jesus was brought to the temple, which old man called Him \"a light for revelation to the Gentiles\"?", a: ["Simeon", "Zechariah", "Nicodemus", "Eli"], ref: "Luke 2:25–32", fact: "God had promised Simeon he would see the Messiah before he died. Isaiah 49:6 had promised a light for the nations." },
  { lvl: 5, cat: "Birth of the King", q: "Which elderly prophetess thanked God when she saw baby Jesus in the temple?", a: ["Anna", "Deborah", "Huldah", "Miriam"], ref: "Luke 2:36–38", fact: "Anna was very old and spent her days praying in the temple. She told everyone who was waiting for God's rescue." },
  { lvl: 5, cat: "Birth of the King", q: "Why couldn't Zechariah speak until John the Baptist was born?", a: ["He didn't believe the angel's message", "He had a cold", "He took a vow of silence", "The priests told him to stop"], ref: "Luke 1:18–20", fact: "When John was born, Zechariah's first words were praise to God." },
  { lvl: 5, cat: "Messengers", q: "Isaiah's \"voice of one calling in the wilderness\" was fulfilled by...", a: ["John the Baptist", "Elijah", "Peter", "Moses"], ref: "Isaiah 40:3; Matthew 3:3", fact: "John's job was to prepare people's hearts for Jesus, like clearing a road for a king." },
  { lvl: 5, cat: "Messengers", q: "Malachi promised God would send ___ before the day of the Lord. Jesus said John the Baptist fulfilled it.", a: ["Elijah", "Moses", "David", "Daniel"], ref: "Malachi 4:5; Matthew 11:14", fact: "In Christian Bibles, Malachi is the last book of the Old Testament. Its last promise points straight to John and Jesus." },
  { lvl: 5, cat: "Messengers", q: "Who called Jesus \"the Lamb of God, who takes away the sin of the world\"?", a: ["John the Baptist", "Peter", "Mary", "Pilate"], ref: "John 1:29", fact: "John's words connect Jesus to every lamb sacrificed in the Old Testament." },
  { lvl: 5, cat: "Messengers", q: "Moses promised God would raise up a prophet like him. Peter said this prophet was...", a: ["Jesus", "Elijah", "Samuel", "John"], ref: "Deuteronomy 18:15; Acts 3:22", fact: "Moses led God's people out of slavery. Jesus leads us out of slavery to sin." },
  { lvl: 5, cat: "Shadows & Pictures", q: "In Genesis 3:15, God promised a descendant of Eve would crush whose head?", a: ["The serpent's", "Pharaoh's", "Goliath's", "A lion's"], ref: "Genesis 3:15", fact: "Right after the first sin, God promised a rescuer. Many call it the first announcement of the gospel." },
  { lvl: 5, cat: "Shadows & Pictures", q: "When Isaac asked where the lamb for the sacrifice was, Abraham said...", a: ["\"God himself will provide the lamb\"", "\"We'll buy one in town\"", "\"There is no lamb\"", "\"You ask too many questions\""], ref: "Genesis 22:8", fact: "God did provide a ram that day, and later provided His own Son as the Lamb." },
  { lvl: 5, cat: "Shadows & Pictures", q: "God promised Abraham that through him, all peoples on earth would be...", a: ["blessed", "ruled", "counted", "scattered"], ref: "Genesis 12:3; Galatians 3:8", fact: "Paul says this promise was the gospel announced ahead of time: Jesus, Abraham's descendant, blesses the whole world." },
  { lvl: 5, cat: "Shadows & Pictures", q: "Like the Passover lamb, which detail did John notice at the cross?", a: ["None of Jesus' bones were broken", "He wore a red robe", "It happened at sunrise", "There were twelve soldiers"], ref: "Exodus 12:46; John 19:33–36", fact: "Jesus died at Passover time, as the true Passover Lamb who saves us." },
  { lvl: 5, cat: "Shadows & Pictures", q: "Jesus said He would be \"lifted up\" like what Moses lifted up in the desert?", a: ["A bronze snake on a pole", "The Ten Commandments", "A golden calf", "A tent"], ref: "Numbers 21:8–9; John 3:14–15", fact: "People bitten by snakes looked at it and lived. Whoever looks to Jesus in faith has eternal life." },
  { lvl: 5, cat: "Shadows & Pictures", q: "Jesus said the \"sign of Jonah\" pointed to what?", a: ["Him being in the grave three days, then rising", "A big storm coming", "Fishing season", "The fall of Nineveh"], ref: "Matthew 12:40", fact: "Jonah came out of the fish after three days. Jesus came out of the tomb on the third day." },
  { lvl: 5, cat: "Shadows & Pictures", q: "Jesus compared Himself to the manna in the desert, saying He is the true...", a: ["bread from heaven", "water from the rock", "pillar of fire", "promised land"], ref: "John 6:32–35", fact: "Manna kept people alive for a day. Jesus gives life forever." },
  { lvl: 5, cat: "Shadows & Pictures", q: "Paul wrote that the rock that gave Israel water in the desert was a picture of whom?", a: ["Christ", "Moses", "Abraham", "The temple"], ref: "1 Corinthians 10:4", fact: "Again and again, the Old Testament stories point forward to Jesus." },
  { lvl: 5, cat: "Shadows & Pictures", q: "Peter compares the water of Noah's flood to...", a: ["baptism", "the Red Sea", "rain in Galilee", "the Jordan River"], ref: "1 Peter 3:20–21", fact: "The ark carried Noah's family safely through the water. Peter connects baptism to being saved through Jesus' resurrection." },
  { lvl: 5, cat: "Shadows & Pictures", q: "What did Joseph tell his brothers about the evil they had done to him?", a: ["\"God intended it for good\"", "\"I'll never forgive you\"", "\"It was no big deal\"", "\"Pharaoh made you do it\""], ref: "Genesis 50:20", fact: "God can turn even the worst things into good, just like He did through Jesus' cross." },
  { lvl: 5, cat: "Son of David", q: "God promised King David that his ___ would last forever. The angel Gabriel said Jesus would fulfill it.", a: ["kingdom", "palace", "army", "harp"], ref: "2 Samuel 7:16; Luke 1:32–33", fact: "Jesus is the forever King from David's family." },
  { lvl: 5, cat: "Son of David", q: "Matthew begins his Gospel by calling Jesus the son of which two people?", a: ["David and Abraham", "Moses and Aaron", "Adam and Noah", "Isaac and Jacob"], ref: "Matthew 1:1", fact: "Those two names remind readers of God's two big promises: a forever King (David) and a blessing for all nations (Abraham)." },
  { lvl: 5, cat: "Son of David", q: "In Revelation, Jesus is called the Lion of the tribe of ___.", a: ["Judah", "Levi", "Benjamin", "Dan"], ref: "Revelation 5:5; Genesis 49:9–10", fact: "Jacob had prophesied that kings would come from Judah. Jesus is that King." },
  { lvl: 5, cat: "Son of David", q: "\"The stone the builders rejected has become the cornerstone.\" Who is the stone?", a: ["Jesus", "David", "Peter", "Solomon"], ref: "Psalm 118:22; Acts 4:10–11", fact: "Jesus was rejected and crucified, but God raised Him and made Him the most important stone in the whole building." },
  { lvl: 5, cat: "Son of David", q: "Jesus often called Himself \"the Son of Man,\" a title from which prophet's vision?", a: ["Daniel", "Jonah", "Joel", "Nahum"], ref: "Daniel 7:13–14; Mark 14:62", fact: "Daniel saw \"one like a son of man\" given a kingdom that would never end." },
  { lvl: 5, cat: "Son of David", q: "Which prophet said the King would come riding on a donkey?", a: ["Zechariah", "Habakkuk", "Obadiah", "Hosea"], ref: "Zechariah 9:9; Matthew 21:4–5", fact: "Kings rode horses to war. A king on a donkey came in peace.", host: "A PROPHECY ABOUT A DONKEY. Finally, the respect we deserve." },
  { lvl: 5, cat: "Son of David", q: "In His hometown synagogue, Jesus read from Isaiah about good news for the poor and then said...", a: ["\"Today this scripture is fulfilled in your hearing\"", "\"Someday this will happen\"", "\"This was about Isaiah\"", "\"Let's read something else\""], ref: "Isaiah 61:1–2; Luke 4:16–21", fact: "Jesus was announcing that He is the one Isaiah wrote about." },
  { lvl: 5, cat: "Son of David", q: "When John the Baptist asked if Jesus was the one, Jesus pointed to...", a: ["Blind people seeing and lame people walking", "His royal family tree", "The crowds following Him", "His fishing skills"], ref: "Isaiah 35:5–6; Matthew 11:4–5", fact: "Jesus was doing exactly what Isaiah said the Messiah would do." },
  { lvl: 5, cat: "The Cross Foretold", q: "When Jesus cried, \"My God, my God, why have you forsaken me?\", which psalm was He quoting?", a: ["Psalm 22", "Psalm 23", "Psalm 1", "Psalm 150"], ref: "Psalm 22:1; Matthew 27:46", fact: "Psalm 22 was written centuries earlier, yet its details match the cross in striking ways, and it ends in victory." },
  { lvl: 5, cat: "The Cross Foretold", q: "Psalm 22 says \"they divide my clothes among them and cast lots.\" Who did that at the cross?", a: ["Roman soldiers", "The disciples", "The priests", "Pilate's family"], ref: "Psalm 22:18; John 19:23–24", fact: "John points out this detail so readers see the psalm coming true." },
  { lvl: 5, cat: "The Cross Foretold", q: "Isaiah 53 says \"by his wounds we are...\"", a: ["healed", "judged", "forgotten", "warned"], ref: "Isaiah 53:5; 1 Peter 2:24", fact: "Isaiah wrote this centuries before the cross, and Peter says it is about Jesus: \"by his wounds you have been healed.\"" },
  { lvl: 5, cat: "The Cross Foretold", q: "Isaiah said the suffering servant would be led like a ___ to the slaughter.", a: ["lamb", "lion", "king", "soldier"], ref: "Isaiah 53:7; Acts 8:32–35", fact: "The Ethiopian official was reading this exact passage when Philip explained it was about Jesus." },
  { lvl: 5, cat: "The Cross Foretold", q: "Isaiah 53 says the servant would be \"with the rich in his death.\" Whose tomb was Jesus buried in?", a: ["Joseph of Arimathea's", "King David's", "Lazarus's", "Peter's"], ref: "Isaiah 53:9; Matthew 27:57–60", fact: "Joseph was a rich man who gave Jesus his own new tomb." },
  { lvl: 5, cat: "The Cross Foretold", q: "Isaiah said the servant would be \"numbered with the transgressors.\" How did that happen?", a: ["Jesus was crucified between two criminals", "Jesus paid taxes", "Jesus was counted in a census", "Jesus ate with fishermen"], ref: "Isaiah 53:12; Luke 22:37; Mark 15:27", fact: "Jesus Himself quoted this verse the night before He died." },
  { lvl: 5, cat: "The Cross Foretold", q: "Jesus quoted Psalm 41 (\"he who shared my bread has turned against me\") about whom?", a: ["Judas", "Peter", "Thomas", "Herod"], ref: "Psalm 41:9; John 13:18", fact: "Even betrayal by a close friend had been foretold." },
  { lvl: 5, cat: "The Cross Foretold", q: "Psalm 69 says \"they gave me vinegar for my thirst.\" When did this happen to Jesus?", a: ["On the cross", "At the Last Supper", "At a wedding", "In the desert"], ref: "Psalm 69:21; John 19:28–30", fact: "Right after, Jesus said, \"It is finished.\"" },
  { lvl: 5, cat: "The Cross Foretold", q: "Zechariah wrote, \"They will look on me, the one they have pierced.\" John connects it to...", a: ["The soldier's spear at the cross", "Peter cutting off an ear", "Stephen being stoned", "Goliath's spear"], ref: "Zechariah 12:10; John 19:34–37", fact: "John was an eyewitness and wrote so that we would believe." },
  { lvl: 5, cat: "Risen & Reigning", q: "On Pentecost, Peter quoted Psalm 16 (\"you will not let your holy one see decay\") to prove what?", a: ["Jesus rose from the dead", "David was still alive", "The temple would stand forever", "Jerusalem would fall"], ref: "Psalm 16:10; Acts 2:27–32", fact: "David died and was buried, so the psalm had to be about someone else: the risen Jesus." },
  { lvl: 5, cat: "Risen & Reigning", q: "Peter said the Holy Spirit's arrival at Pentecost fulfilled a prophecy from which prophet?", a: ["Joel", "Jonah", "Jeremiah", "Malachi"], ref: "Joel 2:28; Acts 2:16–17", fact: "Joel said God would pour out His Spirit on all people, young and old, sons and daughters." },
  { lvl: 5, cat: "Risen & Reigning", q: "At the Last Supper, Jesus said the cup is the new ___ in His blood, which Jeremiah had promised.", a: ["covenant", "temple", "kingdom", "law"], ref: "Jeremiah 31:31–34; Luke 22:20", fact: "A covenant is a promise-relationship. In the new covenant, God writes His law on our hearts." },
  { lvl: 5, cat: "Risen & Reigning", q: "Through Ezekiel, God promised to replace a heart of stone with...", a: ["a heart of flesh", "a heart of gold", "a lion's heart", "a heart of iron"], ref: "Ezekiel 36:26", fact: "God doesn't just ask us to try harder. He promises to give us a new heart." },
  { lvl: 5, cat: "Risen & Reigning", q: "On the road to Emmaus, what did Jesus explain to two disciples?", a: ["What all the Scriptures said about Him", "How to catch fish", "Directions to Jerusalem", "The date of His return"], ref: "Luke 24:27", fact: "That's what this whole mode is about: the entire Bible points to Jesus." },
  { lvl: 5, cat: "Risen & Reigning", q: "Which two Old Testament figures appeared with Jesus at the Transfiguration?", a: ["Moses and Elijah", "Abraham and David", "Noah and Daniel", "Adam and Isaac"], ref: "Matthew 17:1–3", fact: "Moses stands for the Law and Elijah for the Prophets. Both point to Jesus." },
  { lvl: 5, cat: "Risen & Reigning", q: "At the Jerusalem council, James quoted the prophet Amos to show God planned to include...", a: ["Gentiles (non-Jewish people)", "only priests", "only the twelve tribes", "angels"], ref: "Amos 9:11–12; Acts 15:13–17", fact: "God's family was always meant to include people from every nation." },
  { lvl: 5, cat: "Risen & Reigning", q: "In Nebuchadnezzar's dream, what destroyed the giant statue and grew into a mountain?", a: ["A rock not cut by human hands", "A lightning bolt", "A great flood", "An army of angels"], ref: "Daniel 2:34–35, 44", fact: "Daniel explained the rock is God's kingdom, which will never be destroyed." },
  { lvl: 5, cat: "Risen & Reigning", q: "Isaiah 25 and Revelation 21 both promise that God will wipe away every...", a: ["tear", "city", "mountain", "sea monster"], ref: "Isaiah 25:8; Revelation 21:4", fact: "Someday there will be no more death, mourning, crying or pain." },
  { lvl: 5, cat: "Risen & Reigning", q: "What are Jesus' last recorded words in the Bible?", a: ["\"Yes, I am coming soon.\"", "\"It is finished.\"", "\"Follow me.\"", "\"Peace be with you.\""], ref: "Revelation 22:20", fact: "Right before its final blessing, the Bible ends with a promise and a prayer: \"Amen. Come, Lord Jesus.\"" },
  { lvl: 5, cat: "The Prophets", q: "Which prophet named Cyrus, the king who would let the Jews go home, long before Cyrus ruled?", a: ["Isaiah", "Haggai", "Nahum", "Joel"], ref: "Isaiah 44:28; 45:1; Ezra 1:1–3", fact: "God called Cyrus by name to show He is in charge of history." },
  { lvl: 5, cat: "The Prophets", q: "Jeremiah prophesied the exile in Babylon would last how many years?", a: ["70", "7", "40", "400"], ref: "Jeremiah 29:10; Daniel 9:2", fact: "Years later, Daniel read Jeremiah's scroll and realized the 70 years were almost up, so he prayed." },
  { lvl: 5, cat: "The Prophets", q: "\"For I know the plans I have for you,\" declares the LORD. Which prophet wrote this to the exiles?", a: ["Jeremiah", "Isaiah", "Ezekiel", "Amos"], ref: "Jeremiah 29:11", fact: "God sent this hope to people far from home in Babylon, promising He hadn't forgotten them." },
  { lvl: 5, cat: "The Prophets", q: "When God called Jeremiah, what excuse did he give?", a: ["\"I am too young\"", "\"I am too old\"", "\"I'm too busy\"", "\"I can't swim\""], ref: "Jeremiah 1:6–8", fact: "God said, \"Do not say, 'I am too young.'\" God uses young people too!" },
  { lvl: 5, cat: "The Prophets", q: "Who answered God's call by saying, \"Here am I. Send me!\"?", a: ["Isaiah", "Jonah", "Elisha", "Hosea"], ref: "Isaiah 6:8", fact: "Isaiah had just seen a vision of God's holiness and been forgiven, so he was ready to go." },
  { lvl: 5, cat: "The Prophets", q: "Which prophet told King David a story about a stolen lamb, then said, \"You are the man!\"?", a: ["Nathan", "Samuel", "Gad", "Elijah"], ref: "2 Samuel 12:1–7", fact: "Nathan bravely confronted the king, and David repented. Psalm 51 is his prayer afterward." },
  { lvl: 5, cat: "The Prophets", q: "When Jonah finally preached in Nineveh, what happened?", a: ["The whole city turned to God", "They threw him out", "Nobody listened", "Jonah ran away again"], ref: "Jonah 3:5–10", fact: "God showed mercy to Israel's enemies. Jonah was upset, but God cares about everyone." },
  { lvl: 5, cat: "The Prophets", q: "Isaiah gave the \"Immanuel\" sign to which king, who refused to trust God?", a: ["Ahaz", "Hezekiah", "David", "Cyrus"], ref: "Isaiah 7:10–14", fact: "The sign was first spoken to a scared king, then fulfilled completely in Jesus centuries later." },
  { lvl: 5, cat: "The Prophets", q: "Which prophet saw God's throne room, with angels calling \"Holy, holy, holy\"?", a: ["Isaiah", "Amos", "Jonah", "Micah"], ref: "Isaiah 6:1–3", fact: "John says Isaiah saw Jesus' glory in that vision (John 12:41)." },
  { lvl: 5, cat: "The Prophets", q: "What did Elisha ask for before Elijah was taken up to heaven?", a: ["A double portion of his spirit", "Elijah's chariot", "Gold and silver", "A long life"], ref: "2 Kings 2:9", fact: "Elisha went on to do even more recorded miracles than Elijah." },

  // ---------- Scholars: languages, places, history, how the Bible came together ----------
  { lvl: 6, cat: "Languages", q: "In what language was the New Testament originally written?", a: ["Greek", "Latin", "Hebrew", "English"], ref: "Bible history", fact: "Greek was the common language of the Roman world, so the good news could travel far." },
  { lvl: 6, cat: "Languages", q: "Most of the Old Testament was written in Hebrew. Parts of Daniel and Ezra were written in...", a: ["Aramaic", "Greek", "Egyptian", "Latin"], ref: "Daniel 2:4–7:28; Ezra 4:8–6:18", fact: "Aramaic was the language of the Babylonian and Persian empires, where those stories happened." },
  { lvl: 6, cat: "Languages", q: "What does Jesus' Aramaic phrase \"Talitha koum\" mean?", a: ["\"Little girl, get up!\"", "\"Peace, be still!\"", "\"Follow me!\"", "\"I am here!\""], ref: "Mark 5:41", fact: "Mark kept Jesus' exact words, spoken to Jairus's daughter as He raised her from the dead." },
  { lvl: 6, cat: "Languages", q: "Jesus prayed to God as \"Abba.\" What does it mean?", a: ["Father", "King", "Lord", "Teacher"], ref: "Mark 14:36; Romans 8:15", fact: "It's a close, loving word for a dad. Paul says God's children can call Him Abba too." },
  { lvl: 6, cat: "Languages", q: "The Aramaic word \"Maranatha\" that Paul used means...", a: ["\"Come, Lord!\"", "\"Praise God!\"", "\"Amen\"", "\"Good news\""], ref: "1 Corinthians 16:22", fact: "Early Christians prayed it, longing for Jesus to return." },
  { lvl: 6, cat: "Languages", q: "The shout \"Hosanna!\" on Palm Sunday originally meant...", a: ["\"Save us!\"", "\"Welcome home!\"", "\"Long live the king!\"", "\"Hello!\""], ref: "Psalm 118:25; Matthew 21:9", fact: "The crowd was crying out for rescue, and Jesus was the one who could save." },
  { lvl: 6, cat: "Languages", q: "The title \"Christ\" comes from Greek. It means the same as the Hebrew word...", a: ["Messiah", "Rabbi", "Pharaoh", "Hallelujah"], ref: "John 1:41", fact: "Both mean \"Anointed One,\" the chosen King God promised." },
  { lvl: 6, cat: "Languages", q: "The word \"gospel\" means...", a: ["good news", "holy book", "long story", "law"], ref: "Mark 1:1", fact: "Mark's first line: \"The beginning of the good news about Jesus the Messiah.\"" },
  { lvl: 6, cat: "Languages", q: "The first five books of the Bible are called the Pentateuch. What does \"penta\" mean?", a: ["Five", "Law", "Holy", "Old"], ref: "Genesis – Deuteronomy", fact: "It's Greek for \"five scrolls.\" Jewish readers call them the Torah, meaning instruction." },
  { lvl: 6, cat: "Languages", q: "What is the Septuagint?", a: ["An ancient Greek translation of the Old Testament", "The seventh book of the Bible", "A Roman army", "A Jewish holiday"], ref: "Bible history", fact: "Work on it began about 250 years before Jesus. Many New Testament writers quoted from it." },
  { lvl: 6, cat: "Places", q: "The Sea of Galilee is also called the Lake of...", a: ["Gennesaret", "Jericho", "Babylon", "Damascus"], ref: "Luke 5:1; John 21:1", fact: "John also calls it the Sea of Tiberias. It's a freshwater lake where Peter and Andrew fished." },
  { lvl: 6, cat: "Places", q: "The Jordan River flows from the Sea of Galilee into which sea?", a: ["The Dead Sea", "The Red Sea", "The Mediterranean Sea", "The Black Sea"], ref: "Joshua 3:16", fact: "The Bible calls it the Salt Sea. It's so salty that almost nothing can live in it." },
  { lvl: 6, cat: "Places", q: "Jesus grew up in Nazareth, in which region?", a: ["Galilee", "Judea", "Samaria", "Egypt"], ref: "Luke 2:39; Matthew 2:22–23", fact: "Nazareth was a small, ordinary village, which is why Nathanael asked if anything good could come from it." },
  { lvl: 6, cat: "Places", q: "Which lakeside town did Jesus make His home base during His ministry?", a: ["Capernaum", "Bethlehem", "Jerusalem", "Jericho"], ref: "Matthew 4:13", fact: "Many of His miracles happened in and around Capernaum on the Sea of Galilee." },
  { lvl: 6, cat: "Places", q: "Mary, Martha and Lazarus lived in which village near Jerusalem?", a: ["Bethany", "Bethel", "Nazareth", "Cana"], ref: "John 11:1", fact: "Bethany was about two miles from Jerusalem, so Jesus often stayed there." },
  { lvl: 6, cat: "Places", q: "What was Paul's hometown?", a: ["Tarsus", "Rome", "Corinth", "Ephesus"], ref: "Acts 21:39; 22:3", fact: "Tarsus was a big city in what is now Turkey. Paul was born a Roman citizen there." },
  { lvl: 6, cat: "Places", q: "In which city were Jesus' followers first called \"Christians\"?", a: ["Antioch", "Jerusalem", "Rome", "Bethlehem"], ref: "Acts 11:26", fact: "Antioch also sent Paul and Barnabas out on their first missionary journey." },
  { lvl: 6, cat: "Places", q: "In which city did Paul preach about an altar \"to an unknown god\"?", a: ["Athens", "Rome", "Philippi", "Jerusalem"], ref: "Acts 17:22–23", fact: "Paul told the Greek thinkers that the God they didn't know is the Creator of everything." },
  { lvl: 6, cat: "Places", q: "In Ephesus, silversmiths rioted because Paul's preaching hurt their business making shrines of which goddess?", a: ["Artemis", "Athena", "Venus", "Isis"], ref: "Acts 19:24–28", fact: "So many people followed Jesus that the idol business started losing money." },
  { lvl: 6, cat: "Places", q: "Lydia, whom Paul met in Philippi, was a dealer in what?", a: ["Purple cloth", "Spices", "Pottery", "Horses"], ref: "Acts 16:14–15", fact: "Purple dye was very expensive. Lydia opened her home to Paul and his friends." },
  { lvl: 6, cat: "History", q: "Which empire destroyed Jerusalem and Solomon's temple?", a: ["Babylon", "Rome", "Egypt", "Greece"], ref: "2 Kings 25:8–10", fact: "It happened in 586 BC, and many people were taken into exile. Daniel had already been taken to Babylon years earlier." },
  { lvl: 6, cat: "History", q: "Which Persian king let the Jews go home and rebuild the temple?", a: ["Cyrus", "Darius", "Xerxes", "Nebuchadnezzar"], ref: "Ezra 1:1–3", fact: "Isaiah's prophecy calls Cyrus by name, as the one God would use to rebuild Jerusalem (Isaiah 44:28; 45:1)." },
  { lvl: 6, cat: "History", q: "Which empire conquered the northern kingdom of Israel and its capital, Samaria?", a: ["Assyria", "Babylon", "Persia", "Rome"], ref: "2 Kings 17:5–6", fact: "This happened in 722 BC. Years earlier, Jonah had preached to Nineveh, a great Assyrian city." },
  { lvl: 6, cat: "History", q: "Which Roman emperor ordered the census when Jesus was born?", a: ["Caesar Augustus", "Nero", "Julius Caesar", "Tiberius"], ref: "Luke 2:1", fact: "The census moved Mary and Joseph to Bethlehem, right where Micah said the Messiah would be born." },
  { lvl: 6, cat: "History", q: "Which king ruled Judea when Jesus was born?", a: ["Herod the Great", "Herod Agrippa", "King Saul", "Pontius Pilate"], ref: "Matthew 2:1", fact: "Herod was a powerful builder who rebuilt the temple, but he was jealous and cruel." },
  { lvl: 6, cat: "History", q: "Which group did NOT believe in the resurrection of the dead?", a: ["The Sadducees", "The Pharisees", "The disciples", "Martha of Bethany"], ref: "Acts 23:8; Matthew 22:23", fact: "Paul once got the Pharisees and Sadducees arguing with each other about this!" },
  { lvl: 6, cat: "History", q: "The time of the judges came between which two eras?", a: ["Joshua's conquest and Israel's kings", "Creation and the flood", "The exile and Jesus", "Moses and Joseph"], ref: "Judges 2:16; 1 Samuel 8:5", fact: "It was a messy time. \"Everyone did as they saw fit\" (Judges 21:25)." },
  { lvl: 6, cat: "History", q: "Who lived FIRST?", a: ["Abraham", "Moses", "David", "Daniel"], ref: "Genesis 12; Exodus 3; 1 Samuel 16; Daniel 1", fact: "The order: Abraham, then Moses, then David, then Daniel, spread over about 1,500 years." },
  { lvl: 6, cat: "History", q: "Who lived LAST?", a: ["Nehemiah", "Joshua", "Samuel", "Elijah"], ref: "Nehemiah 1–2", fact: "Nehemiah rebuilt Jerusalem's walls after the exile, one of the last Old Testament stories." },
  { lvl: 6, cat: "Tribes & Numbers", q: "After King Solomon, Israel split. How many tribes made up the northern kingdom?", a: ["10", "2", "7", "12"], ref: "1 Kings 11:31", fact: "The northern kingdom kept the name Israel. The southern kingdom was called Judah." },
  { lvl: 6, cat: "Tribes & Numbers", q: "Which tribe received no land of its own because it served God at the tabernacle?", a: ["Levi", "Judah", "Reuben", "Dan"], ref: "Joshua 13:14, 33", fact: "God said He Himself was the Levites' inheritance." },
  { lvl: 6, cat: "Tribes & Numbers", q: "Joseph's two sons each became a tribe. What were their names?", a: ["Ephraim and Manasseh", "Cain and Abel", "Jacob and Esau", "Perez and Zerah"], ref: "Genesis 48:5", fact: "That's how there are still twelve tribes with land, even though Levi got none." },
  { lvl: 6, cat: "Tribes & Numbers", q: "How long did Israel wander in the wilderness?", a: ["40 years", "7 years", "70 years", "400 years"], ref: "Numbers 14:33–34", fact: "One year for each of the 40 days the spies explored Canaan." },
  { lvl: 6, cat: "Tribes & Numbers", q: "About how old was Jesus when He began His ministry?", a: ["30", "12", "18", "40"], ref: "Luke 3:23", fact: "Levites began serving at the tabernacle at 30 (Numbers 4:3), and David became king at 30 (2 Samuel 5:4)." },
  { lvl: 6, cat: "Tribes & Numbers", q: "How old was Jesus when His parents found Him in the temple talking with the teachers?", a: ["12", "8", "16", "30"], ref: "Luke 2:42–49", fact: "Everyone was amazed at His understanding. He said, \"I had to be in my Father's house.\"" },
  { lvl: 6, cat: "Tribes & Numbers", q: "How many New Testament letters begin with Paul's name?", a: ["13", "7", "21", "4"], ref: "Romans 1:1 – Philemon 1:1", fact: "Romans through Philemon. Many of them were written to churches he had started." },
  { lvl: 6, cat: "Temple & Tabernacle", q: "What was kept inside the Most Holy Place of the tabernacle?", a: ["The ark of the covenant", "The golden lampstand", "The bronze altar", "The table of bread"], ref: "Exodus 26:33–34", fact: "The Most Holy Place, or Holy of Holies, was the inner room where God's presence rested." },
  { lvl: 6, cat: "Temple & Tabernacle", q: "How often could the high priest enter the Most Holy Place?", a: ["Once a year", "Every day", "Every Sabbath", "Never"], ref: "Leviticus 16:2, 34; Hebrews 9:7", fact: "It happened on the Day of Atonement, when he made a sacrifice for the people's sins." },
  { lvl: 6, cat: "Temple & Tabernacle", q: "When Jesus died, what happened to the curtain in the temple?", a: ["It tore from top to bottom", "It caught fire", "It turned gold", "Nothing happened"], ref: "Matthew 27:51; Hebrews 10:19–20", fact: "Torn from the top, as if God did it. The way into God's presence was now open through Jesus." },
  { lvl: 6, cat: "Temple & Tabernacle", q: "Which of these was NOT kept in the ark of the covenant?", a: ["Goliath's sword", "The stone tablets of the covenant", "A jar of manna", "Aaron's staff that budded"], ref: "Hebrews 9:4; 1 Samuel 21:9", fact: "Goliath's sword was kept by the priests at Nob, wrapped in a cloth. David picked it up later." },
  { lvl: 6, cat: "Feasts", q: "Pentecost means \"fiftieth.\" It came 50 days after which feast?", a: ["Passover", "Purim", "Tabernacles", "Hanukkah"], ref: "Leviticus 23:15–16; Acts 2:1", fact: "Jesus died at Passover time. About fifty days later, the Holy Spirit came at Pentecost." },
  { lvl: 6, cat: "Feasts", q: "During the Feast of Tabernacles, what did Israelites live in for a week?", a: ["Temporary shelters (booths)", "Tents made of gold", "Caves", "The temple"], ref: "Leviticus 23:42–43", fact: "It reminded them that God cared for them while they lived in tents in the wilderness." },
  { lvl: 6, cat: "Feasts", q: "Which Jewish festival celebrates the story of Queen Esther?", a: ["Purim", "Passover", "Pentecost", "Tabernacles"], ref: "Esther 9:26–28", fact: "\"Purim\" comes from \"pur,\" the lots Haman threw to pick a day to harm the Jewish people. Esther's courage saved them." },
  { lvl: 6, cat: "Feasts", q: "In John 10:22, Jesus was at the temple for which festival, known today as Hanukkah?", a: ["The Festival of Dedication", "The Feast of Weeks", "The Day of Atonement", "The New Moon"], ref: "John 10:22–23", fact: "Hanukkah remembers when the temple was cleansed and dedicated again, about 165 years before Jesus." },
  { lvl: 6, cat: "Books & Authors", q: "Who is traditionally credited with writing the first five books of the Bible?", a: ["Moses", "Abraham", "David", "Ezra"], ref: "Deuteronomy 31:24; John 5:46", fact: "These books are called the Torah, or the Law. Jesus said Moses wrote about Him." },
  { lvl: 6, cat: "Books & Authors", q: "Who wrote most of the book of Proverbs?", a: ["Solomon", "David", "Moses", "Daniel"], ref: "Proverbs 1:1", fact: "Solomon asked God for wisdom, and Proverbs is full of it." },
  { lvl: 6, cat: "Books & Authors", q: "Which prophet is traditionally believed to have written Lamentations?", a: ["Jeremiah", "Isaiah", "Ezekiel", "Joel"], ref: "Lamentations 1:1; 2 Chronicles 35:25", fact: "It's a book of grief over Jerusalem's fall, but in the middle it says God's mercies are new every morning (3:22–23)." },
  { lvl: 6, cat: "Books & Authors", q: "Luke and Acts were both written to a man named...", a: ["Theophilus", "Timothy", "Titus", "Philemon"], ref: "Luke 1:3; Acts 1:1", fact: "Acts picks up right where Luke leaves off. They're a two-part story." },
  { lvl: 6, cat: "Books & Authors", q: "Which of these letters did Paul write while in prison?", a: ["Philippians", "Romans", "Galatians", "1 Corinthians"], ref: "Philippians 1:12–14", fact: "Even in chains, Paul wrote, \"Rejoice in the Lord always.\" Ephesians, Colossians and Philemon are prison letters too." },
  { lvl: 6, cat: "Books & Authors", q: "Which of these New Testament letters does not name its author?", a: ["Hebrews", "Romans", "James", "Jude"], ref: "Hebrews 1:1", fact: "People have guessed Paul, Barnabas or Apollos, but nobody knows for sure." },
  { lvl: 6, cat: "Books & Authors", q: "Which Gospel is NOT one of the three \"Synoptic Gospels\" that share many of the same stories?", a: ["John", "Matthew", "Mark", "Luke"], ref: "John 20:31", fact: "John tells many stories the others don't, and says he wrote so that you may believe." },
  { lvl: 6, cat: "Books & Authors", q: "Which book comes right after Acts?", a: ["Romans", "Revelation", "Galatians", "James"], ref: "Bible order", fact: "After the history book (Acts) come the letters, starting with Romans." },
  { lvl: 6, cat: "Books & Authors", q: "Which book comes right before Matthew?", a: ["Malachi", "Psalms", "Revelation", "Jonah"], ref: "Bible order", fact: "About 400 years passed between Malachi and the birth of Jesus." },
  { lvl: 6, cat: "Books & Authors", q: "When Satan tempted Jesus in the desert, Jesus answered each time by quoting which book?", a: ["Deuteronomy", "Psalms", "Genesis", "Isaiah"], ref: "Matthew 4:4, 7, 10", fact: "Jesus fought temptation with Scripture. That's a strategy anyone can use." },
  { lvl: 6, cat: "Books & Authors", q: "The Shema prayer begins \"Hear, O Israel: The LORD our God, the LORD is one.\" Which book is it from?", a: ["Deuteronomy", "Leviticus", "Psalms", "Ruth"], ref: "Deuteronomy 6:4–5", fact: "Jesus called the next verse, about loving God with all your heart, the greatest commandment." },
  { lvl: 6, cat: "Books & Authors", q: "The Ten Commandments are listed in Exodus 20 and in which other book?", a: ["Deuteronomy", "Numbers", "Joshua", "Judges"], ref: "Deuteronomy 5:6–21", fact: "Deuteronomy means \"second law.\" Moses repeated the law to a new generation." },
  { lvl: 6, cat: "How We Got the Bible", q: "Psalm 119, the longest chapter in the Bible, is organized around what?", a: ["The 22 letters of the Hebrew alphabet", "The 12 tribes", "The days of the week", "The 10 commandments"], ref: "Psalm 119", fact: "Each section of eight verses starts with the next Hebrew letter. Almost every verse mentions God's word." },
  { lvl: 6, cat: "How We Got the Bible", q: "What is the shortest chapter in the Bible?", a: ["Psalm 117", "John 11", "Genesis 1", "Jude 1"], ref: "Psalm 117", fact: "Just two verses: praise the LORD, all you nations, for great is His love." },
  { lvl: 6, cat: "How We Got the Bible", q: "The Dead Sea Scrolls, found in 1947, include an almost complete copy of which book?", a: ["Isaiah", "Revelation", "Acts", "Romans"], ref: "Bible history", fact: "The Great Isaiah Scroll is over 2,000 years old and matches our Bibles remarkably closely." },
  { lvl: 6, cat: "How We Got the Bible", q: "The chapter numbers in our Bibles were added...", a: ["Centuries later, around the 1200s", "By Moses", "By the apostles", "In the 1990s"], ref: "Bible history", fact: "The original writers didn't use chapters or verses. They were added later to make finding passages easier." },

  // ---------- Holy of Holies (unlocked): the hardest deep cuts ----------
  { lvl: 7, cat: "Taken Up", q: "Which two people in the Bible were taken by God without dying?", a: ["Enoch and Elijah", "Moses and Aaron", "Abraham and Isaac", "Elisha and Samuel"], ref: "Genesis 5:24; 2 Kings 2:11", fact: "Hebrews 11:5 says Enoch \"pleased God\" and was taken so he did not experience death." },
  { lvl: 7, cat: "Numbers", q: "How old was Moses when he spoke to Pharaoh?", a: ["80", "40", "120", "25"], ref: "Exodus 7:7", fact: "Aaron was 83. God's biggest assignments don't always come early in life." },
  { lvl: 7, cat: "Numbers", q: "Who was older, Moses or Aaron?", a: ["Aaron", "Moses", "They were twins", "The Bible doesn't say"], ref: "Exodus 7:7", fact: "Aaron was three years older and became Moses' spokesman." },
  { lvl: 7, cat: "Numbers", q: "How old was Abraham when Isaac was born?", a: ["100", "75", "90", "120"], ref: "Genesis 21:5", fact: "Sarah was 90. God kept a promise that seemed impossible." },
  { lvl: 7, cat: "Numbers", q: "How many extra years of life did God give King Hezekiah?", a: ["15", "5", "40", "100"], ref: "2 Kings 20:6", fact: "God heard his prayer and saw his tears." },
  { lvl: 7, cat: "Numbers", q: "In Jesus' second big feeding miracle, with seven loaves, how many men were fed?", a: ["4,000", "5,000", "3,000", "12,000"], ref: "Matthew 15:34–38", fact: "Seven baskets were left over. Jesus did it twice, so His disciples would trust Him." },
  { lvl: 7, cat: "Numbers", q: "Which miracle is the only one (besides the resurrection) recorded in all four Gospels?", a: ["Feeding the 5,000", "Walking on water", "Turning water into wine", "Raising Lazarus"], ref: "Matthew 14; Mark 6; Luke 9; John 6", fact: "Every Gospel writer thought this one was too important to leave out." },
  { lvl: 7, cat: "Numbers", q: "How many prophets of Baal did Elijah face on Mount Carmel?", a: ["450", "50", "1,000", "12"], ref: "1 Kings 18:22", fact: "One prophet of God against 450. Numbers don't matter when God shows up." },
  { lvl: 7, cat: "Numbers", q: "How many years did it take Solomon to build the temple?", a: ["7", "40", "1", "20"], ref: "1 Kings 6:38", fact: "His own palace took 13 years (1 Kings 7:1)." },
  { lvl: 7, cat: "Numbers", q: "Pharaoh's dream of fat and skinny cows predicted how many years of plenty?", a: ["7", "3", "10", "12"], ref: "Genesis 41:29–30", fact: "Joseph's plan saved Egypt and his own family during the famine that followed." },
  { lvl: 7, cat: "Family Trees", q: "Who was the father of John the Baptist?", a: ["Zechariah", "Zebedee", "Joseph", "Simeon"], ref: "Luke 1:13", fact: "Zechariah was a priest serving in the temple when an angel told him the news." },
  { lvl: 7, cat: "Family Trees", q: "James and John were the sons of...", a: ["Zebedee", "Zechariah", "Alphaeus", "Jonah"], ref: "Matthew 4:21", fact: "They left their father in the boat to follow Jesus." },
  { lvl: 7, cat: "Family Trees", q: "Which disciple brought his brother Simon Peter to Jesus?", a: ["Andrew", "John", "Philip", "James"], ref: "John 1:40–42", fact: "Andrew is often found bringing people to Jesus, including the boy with the loaves." },
  { lvl: 7, cat: "Family Trees", q: "Rachel was the mother of which two of Jacob's sons?", a: ["Joseph and Benjamin", "Reuben and Simeon", "Judah and Levi", "Dan and Naphtali"], ref: "Genesis 30:22–24; 35:18", fact: "Rachel was the wife Jacob loved most, and he favored her sons. That favoritism caused a lot of jealousy (Genesis 37:3–4)." },
  { lvl: 7, cat: "Family Trees", q: "Who was Jacob's youngest son?", a: ["Benjamin", "Joseph", "Judah", "Levi"], ref: "Genesis 35:18", fact: "Rachel named him Ben-Oni, but Jacob renamed him Benjamin, \"son of my right hand.\"" },
  { lvl: 7, cat: "Family Trees", q: "Who was Moses' father-in-law?", a: ["Jethro", "Laban", "Eli", "Boaz"], ref: "Exodus 3:1; 18:17–24", fact: "Jethro gave Moses great advice: share the work with other leaders." },
  { lvl: 7, cat: "Family Trees", q: "Which woman who hid Israel's spies is listed in Jesus' family tree?", a: ["Rahab", "Delilah", "Jezebel", "Miriam"], ref: "Joshua 2; Matthew 1:5", fact: "Rahab was a Canaanite outsider. God's family has always been open to people who trust Him." },
  { lvl: 7, cat: "Family Trees", q: "Who was the mother of Samuel, who prayed so hard and so quietly that the priest misunderstood her?", a: ["Hannah", "Peninnah", "Naomi", "Elizabeth"], ref: "1 Samuel 1:12–20", fact: "God answered her prayer, and she dedicated Samuel to serve Him." },
  { lvl: 7, cat: "Family Trees", q: "Which priest raised young Samuel at the tabernacle?", a: ["Eli", "Aaron", "Zadok", "Ezra"], ref: "1 Samuel 2:11; 3:1", fact: "Eli taught Samuel to answer, \"Speak, LORD, for your servant is listening.\"" },
  { lvl: 7, cat: "Kings of Judah", q: "Who was the first king of Judah after the kingdom split?", a: ["Rehoboam", "Jeroboam", "Asa", "Jehoshaphat"], ref: "1 Kings 12:17", fact: "Solomon's son ignored wise advice, and ten tribes walked away." },
  { lvl: 7, cat: "Kings of Judah", q: "Which king of Judah began ruling at age 8, and in whose reign was the lost Book of the Law found?", a: ["Josiah", "Joash", "Hezekiah", "Manasseh"], ref: "2 Kings 22:1, 8–13", fact: "When it was read to him, he tore his robes and led the nation back to God." },
  { lvl: 7, cat: "Kings of Judah", q: "Which king of Judah started ruling at age 7 after being hidden in the temple as a baby?", a: ["Joash", "Josiah", "Uzziah", "Ahaz"], ref: "2 Kings 11:2–3, 21", fact: "His aunt Jehosheba hid him for six years to save his life." },
  { lvl: 7, cat: "Kings of Judah", q: "Who was the only queen to rule Judah on her own?", a: ["Athaliah", "Jezebel", "Esther", "Bathsheba"], ref: "2 Kings 11:1–3", fact: "She seized power for six years until young Joash was crowned." },
  { lvl: 7, cat: "Kings of Judah", q: "Which king burned the prophet Jeremiah's scroll piece by piece?", a: ["Jehoiakim", "Josiah", "Hezekiah", "Zedekiah"], ref: "Jeremiah 36:23, 27–28", fact: "God simply had Jeremiah write it all again. You can't destroy God's word." },
  { lvl: 7, cat: "Names & Meanings", q: "The name \"Bethlehem\" means...", a: ["House of bread", "City of kings", "Place of peace", "Hill of stars"], ref: "Micah 5:2; John 6:35", fact: "The Bread of Life was born in the House of Bread." },
  { lvl: 7, cat: "Names & Meanings", q: "The name \"Jesus\" (Yeshua) means...", a: ["The LORD saves", "God is great", "Prince of peace", "Beloved son"], ref: "Matthew 1:21", fact: "The angel said, \"You are to give him the name Jesus, because he will save his people from their sins.\"" },
  { lvl: 7, cat: "Names & Meanings", q: "When God renamed Jacob \"Israel,\" what did the name refer to?", a: ["Struggling with God", "Being the oldest", "A great king", "A land of milk and honey"], ref: "Genesis 32:28", fact: "God said, \"You have struggled with God and with humans and have overcome.\"" },
  { lvl: 7, cat: "Names & Meanings", q: "God changed Abram's name to Abraham, which means...", a: ["Father of many", "Friend of God", "Man of faith", "Great traveler"], ref: "Genesis 17:5", fact: "Isaac, the promised son, hadn't been born yet when God gave him this name. God was speaking His promise ahead of time." },
  { lvl: 7, cat: "Names & Meanings", q: "Jacob named the place where he wrestled \"Peniel.\" What does it mean?", a: ["Face of God", "House of God", "God will provide", "Holy ground"], ref: "Genesis 32:30", fact: "He said, \"I saw God face to face, and yet my life was spared.\"" },
  { lvl: 7, cat: "Names & Meanings", q: "Gideon was also called Jerub-Baal. Why?", a: ["He tore down Baal's altar", "He was a priest of Baal", "He was born in Baal's temple", "He defeated a giant named Baal"], ref: "Judges 6:28–32", fact: "The name means \"let Baal contend,\" basically: if Baal is real, let him fight back. He couldn't." },
  { lvl: 7, cat: "Names & Meanings", q: "In Daniel's vision, the \"Ancient of Days\" is a name for...", a: ["God", "An angel", "Daniel", "A king of Persia"], ref: "Daniel 7:9, 13–14", fact: "The Son of Man comes to the Ancient of Days and receives an everlasting kingdom." },
  { lvl: 7, cat: "Names & Meanings", q: "What were the Hebrew names of Daniel's friends Shadrach, Meshach and Abednego?", a: ["Hananiah, Mishael and Azariah", "Hezekiah, Micah and Amos", "Hosea, Joel and Obadiah", "Ezra, Nehemiah and Haggai"], ref: "Daniel 1:6–7", fact: "Babylon changed their names, but it couldn't change who they worshiped." },
  { lvl: 7, cat: "Wilderness", q: "Which two spies gave a good report about the Promised Land?", a: ["Joshua and Caleb", "Moses and Aaron", "Eldad and Medad", "Nadab and Abihu"], ref: "Numbers 14:6–9", fact: "Ten spies saw giants. Two saw that God was bigger. Only those two from their generation entered the land." },
  { lvl: 7, cat: "Wilderness", q: "What did the spies carry back from Canaan on a pole between two men?", a: ["A huge cluster of grapes", "A giant's sword", "A golden statue", "A lamb"], ref: "Numbers 13:23", fact: "The land really was flowing with good things, just like God promised." },
  { lvl: 7, cat: "Wilderness", q: "Why wasn't Moses allowed to enter the Promised Land?", a: ["He struck the rock instead of speaking to it", "He was too old", "He went back to Egypt", "He lost the stone tablets"], ref: "Numbers 20:8–12", fact: "God takes trust seriously, even for great leaders. Centuries later, Moses appeared with Jesus at the Transfiguration." },
  { lvl: 7, cat: "Wilderness", q: "From which mountain did Moses see the Promised Land before he died?", a: ["Mount Nebo", "Mount Sinai", "Mount Carmel", "Mount Zion"], ref: "Deuteronomy 34:1–6", fact: "God Himself buried Moses, and no one knows where his grave is." },
  { lvl: 7, cat: "Prophets' Signs", q: "Which prophet lay on his side for 390 days as a sign to Israel?", a: ["Ezekiel", "Jeremiah", "Hosea", "Isaiah"], ref: "Ezekiel 4:4–5", fact: "Prophets sometimes acted out God's messages so people couldn't ignore them." },
  { lvl: 7, cat: "Prophets' Signs", q: "Elijah raised a widow's son from the dead in which town?", a: ["Zarephath", "Jericho", "Bethel", "Shiloh"], ref: "1 Kings 17:9, 17–23", fact: "Jesus mentioned this widow in His hometown sermon (Luke 4:26)." },
  { lvl: 7, cat: "Prophets' Signs", q: "Naaman was an army commander from which country?", a: ["Aram (Syria)", "Egypt", "Babylon", "Moab"], ref: "2 Kings 5:1", fact: "An enemy commander was healed by Israel's God after a young Israelite servant girl spoke up." },
  { lvl: 7, cat: "Prophets' Signs", q: "Gehazi was the servant of which prophet?", a: ["Elisha", "Elijah", "Samuel", "Isaiah"], ref: "2 Kings 5:20–27", fact: "Gehazi lied to get Naaman's money and was punished. Greed costs more than it gives." },
  { lvl: 7, cat: "Prophets' Signs", q: "What did Elisha make float on the water?", a: ["An iron axe head", "A stone tablet", "A golden crown", "A clay jar"], ref: "2 Kings 6:5–7", fact: "The axe was borrowed. God cares about even small problems." },
  { lvl: 7, cat: "Prophets' Signs", q: "Which prophet bought a field while Jerusalem was under attack, as a sign of hope?", a: ["Jeremiah", "Ezekiel", "Daniel", "Habakkuk"], ref: "Jeremiah 32:6–15", fact: "It said: someday people will buy fields here again. God's people would come home." },
  { lvl: 7, cat: "Prophets' Signs", q: "What did Jeremiah's helper Baruch do?", a: ["Wrote down Jeremiah's words on a scroll", "Fought in the army", "Built the city walls", "Rebuilt the temple"], ref: "Jeremiah 36:4", fact: "Baruch was Jeremiah's scribe, a faithful friend in a dangerous time." },
  { lvl: 7, cat: "Prophets' Signs", q: "What did Daniel and his friends eat instead of the king's food?", a: ["Vegetables and water", "Only bread", "Nothing for ten days", "Fish and honey"], ref: "Daniel 1:12–15", fact: "After ten days they looked healthier than everyone else." },
  { lvl: 7, cat: "Early Church", q: "Early church tradition names John Mark, who traveled with Paul and Barnabas, as the writer of which Gospel?", a: ["Mark", "Luke", "Matthew", "John"], ref: "Acts 12:25; 15:37", fact: "He quit partway through a trip, but later Paul said he was very helpful (2 Timothy 4:11). Second chances matter." },
  { lvl: 7, cat: "Early Church", q: "Who argued with Paul about taking John Mark along, so they split up?", a: ["Barnabas", "Silas", "Peter", "Timothy"], ref: "Acts 15:37–39", fact: "Barnabas gave Mark another chance, and the early church remembered Mark as the writer of a Gospel.", host: "My namesake! Even the son of encouragement had a disagreement." },
  { lvl: 7, cat: "Early Church", q: "Which apostle was the first of the Twelve to be killed for his faith, by King Herod?", a: ["James, brother of John", "Peter", "Andrew", "Thomas"], ref: "Acts 12:1–2", fact: "Right after, Herod arrested Peter, and an angel set him free." },
  { lvl: 7, cat: "Early Church", q: "In Acts 9, whom did God send to pray for Saul after he was blinded?", a: ["Ananias", "Peter", "Barnabas", "Stephen"], ref: "Acts 9:10–17", fact: "Ananias was afraid of Saul, but he went anyway and called him \"Brother Saul.\"" },
  { lvl: 7, cat: "Early Church", q: "What fell from Saul's eyes when his sight came back?", a: ["Something like scales", "Tears of gold", "Dust", "Feathers"], ref: "Acts 9:18", fact: "He was baptized right away and started preaching about Jesus." },
  { lvl: 7, cat: "Early Church", q: "In Lystra, people thought Barnabas and Paul were which Greek gods?", a: ["Zeus and Hermes", "Apollo and Ares", "Poseidon and Hades", "Athena and Artemis"], ref: "Acts 14:11–15", fact: "They tore their clothes and said, \"We too are only human!\"" },
  { lvl: 7, cat: "Early Church", q: "Which disciple, known for making clothes for widows, did Peter raise from the dead?", a: ["Tabitha (Dorcas)", "Lydia", "Priscilla", "Rhoda"], ref: "Acts 9:36–41", fact: "Peter used almost the same words Jesus did: \"Tabitha, get up.\"" },
  { lvl: 7, cat: "Early Church", q: "From the cross, Jesus asked \"the disciple whom he loved\" to care for whom?", a: ["His mother, Mary", "Peter", "Mary Magdalene", "Joseph of Arimathea"], ref: "John 19:26–27", fact: "Even while dying, Jesus took care of His family." },
  { lvl: 7, cat: "Early Church", q: "In 1 Timothy, which young pastor did Paul call \"my true son in the faith\"?", a: ["Timothy", "Apollos", "Silas", "Luke"], ref: "1 Timothy 1:2", fact: "Timothy was young, but Paul told him to set an example for everyone (1 Timothy 4:12)." },
  { lvl: 7, cat: "Deep Doctrine", q: "In Galatians 5, the fruit of the Spirit is contrasted with...", a: ["The acts of the flesh", "The laws of Rome", "The fruit of the trees", "The gifts of the angels"], ref: "Galatians 5:19–23", fact: "Living by the Spirit grows good fruit. Selfish living grows the opposite." },
  { lvl: 7, cat: "Deep Doctrine", q: "Which piece of the armor of God is a weapon for fighting back?", a: ["The sword of the Spirit, the word of God", "The shield of faith", "The helmet of salvation", "The belt of truth"], ref: "Ephesians 6:17", fact: "Every other piece protects. God's word is how we fight back, just like Jesus did when He was tempted." },
  { lvl: 7, cat: "Deep Doctrine", q: "Which chapter lists heroes of faith like Abel, Noah, Abraham and Rahab?", a: ["Hebrews 11", "Romans 8", "Psalm 23", "John 3"], ref: "Hebrews 11", fact: "Hebrews 12 then says that since we are surrounded by such a great cloud of witnesses, we should run with perseverance the race marked out for us." },
  { lvl: 7, cat: "Deep Doctrine", q: "Hebrews 11:1 says faith is confidence in what we hope for and assurance about...", a: ["what we do not see", "what we can earn", "what we already have", "what others tell us"], ref: "Hebrews 11:1", fact: "Faith is trusting God's promises even before we see them come true." },
  { lvl: 7, cat: "Deep Doctrine", q: "Romans 3:23 says all have sinned and fall short of...", a: ["the glory of God", "the law of Moses", "their parents' rules", "the angels"], ref: "Romans 3:23–24", fact: "The next verse says we are made right with God freely by His grace through Jesus." },
  { lvl: 7, cat: "Deep Doctrine", q: "\"The wages of sin is death, but the gift of God is...\"", a: ["eternal life in Christ Jesus", "a long life on earth", "a second chance to earn it", "riches in heaven"], ref: "Romans 6:23", fact: "Wages are earned. A gift is free. That's the difference between sin and grace." },
  { lvl: 7, cat: "Deep Doctrine", q: "\"For it is by ___ you have been saved, through faith.\"", a: ["grace", "works", "law", "luck"], ref: "Ephesians 2:8–9", fact: "It's not from ourselves. It's God's gift, so nobody can brag." },
  { lvl: 7, cat: "Deep Doctrine", q: "Paul said nothing can separate us from the love of God. Which chapter says this?", a: ["Romans 8", "Genesis 3", "Judges 16", "Esther 4"], ref: "Romans 8:38–39", fact: "Not death, not life, not angels, not anything in all creation." },
);

